using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class InMemoryCatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public InMemoryCatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
        };

        var instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor", Email = "s.chen@university.edu", Bio = "Dr. Chen has over 15 years of experience in software engineering and artificial intelligence. She holds a PhD from MIT and has published extensively in top-tier journals. Her research focuses on machine learning applications in healthcare.", PhotoUrl = "" },
            new() { Id = 2, Name = "Dr. James Miller", Title = "Associate Professor", Email = "j.miller@university.edu", Bio = "Dr. Miller specializes in data structures and algorithm design. He received his PhD from Stanford and has worked at Google Research before joining academia. He is passionate about teaching and mentoring students.", PhotoUrl = "" },
            new() { Id = 3, Name = "Dr. Emily Rodriguez", Title = "Professor", Email = "e.rodriguez@university.edu", Bio = "Dr. Rodriguez is an expert in abstract algebra and number theory. She has been awarded multiple NSF grants and is the author of two widely adopted textbooks.", PhotoUrl = "" },
            new() { Id = 4, Name = "Dr. Michael Thompson", Title = "Associate Professor", Email = "m.thompson@university.edu", Bio = "Dr. Thompson's research interests include quantum mechanics and particle physics. He completed postdoctoral work at CERN and brings real-world experimental experience to the classroom.", PhotoUrl = "" },
            new() { Id = 5, Name = "Dr. Lisa Park", Title = "Professor", Email = "l.park@university.edu", Bio = "Dr. Park is a literary scholar specializing in 20th-century American literature. She is a published novelist and brings creative writing expertise to her teaching.", PhotoUrl = "" },
            new() { Id = 6, Name = "Dr. Robert Wilson", Title = "Associate Professor", Email = "r.wilson@university.edu", Bio = "Dr. Wilson studies modern European history with a focus on the World Wars. He has authored three books and regularly contributes to historical journals.", PhotoUrl = "" },
        };

        _courses = new List<Course>
