+            new() { Id = 13, Code = "HIST 202", Title = "Modern European History", Description = "Europe from the French Revolution to the present. Covers political revolutions, industrialization, world wars, and the European Union.", Credits = 3, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Humanities Hall 305", DepartmentId = 5, DepartmentName = "History", Instructor = instructors[5], IsFeatured = false, MaxEnrollment = 50, CurrentEnrollment = 38 },
+        };
+    }
+
+    public Task<List<Department>> GetDepartmentsAsync()
+    {
+        return Task.FromResult(_departments.ToList());
+    }
+
+    public Task<List<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null)
+    {
+        var query = _courses.AsEnumerable();
+
+        if (!string.IsNullOrWhiteSpace(searchTerm))
+        {
+            var term = searchTerm.Trim();
+            query = query.Where(c =>
+                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
+                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
+                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase) ||
+                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
+        }
+
+        if (departmentId.HasValue && departmentId.Value > 0)
+        {
+            query = query.Where(c => c.DepartmentId == departmentId.Value);
+        }
+
+        return Task.FromResult(query.ToList());
+    }
+
+    public Task<Course?> GetCourseByIdAsync(int id)
+    {
+        return Task.FromResult(_courses.FirstOrDefault(c => c.Id == id));
+    }
+
+    public Task<List<Course>> GetFeaturedCoursesAsync()
+    {
+        return Task.FromResult(_courses.Where(c => c.IsFeatured).ToList());
+    }
+
+    public Task<bool> SubmitEnrollmentRequestAsync(EnrollmentRequest request)
+    {
+        // In a real app, this would persist to a database
+        return Task.FromResult(true);
+    }
+}
