        <div class="d-flex justify-content-between align-items-start mb-2">
            <span class="badge bg-primary">@Course.Code</span>
            <span class="badge bg-secondary">@Course.Credits Credits</span>
        </div>
        <h5 class="card-title">@Course.Title</h5>
