@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Components.Shared
@inject ICatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="text-center mb-5">
    <h1 class="display-4">University Course Catalog</h1>
    <p class="lead text-muted">Browse departments, explore courses, and submit enrollment requests.</p>
    <a href="catalog" class="btn btn-primary btn-lg me-2">Browse All Courses</a>
    <a href="enroll" class="btn btn-outline-primary btn-lg">Enroll Now</a>
</div>

<section class="mb-5">
    <h2 class="mb-3">Featured Courses</h2>
    @if (_featuredCourses is null)
    {
        <p><em>Loading…</em></p>
    }
    else
    {
        <FeaturedCourses Courses="_featuredCourses" />
    }
</section>

<section>
    <h2 class="mb-3">Departments</h2>
    @if (_departments is null)
    {
        <p><em>Loading…</em></p>
    }
    else
    {
        <DepartmentLinks Departments="_departments" />
    }
</section>

@code {
    private List<Course>? _featuredCourses;
    private List<Department>? _departments;

    protected override async Task OnInitializedAsync()
    {
        _featuredCourses = await CatalogService.GetFeaturedCoursesAsync();
        _departments = await CatalogService.GetDepartmentsAsync();
    }
}

toolArgs.file_text:
@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request has been received. You will be notified once it has been processed.</p>
        <hr />
        <p class="mb-0">
            <a href="catalog" class="btn btn-outline-success me-2">Browse More Courses</a>
            <a href="enroll" class="btn btn-success" @onclick="ResetForm" @onclick:preventDefault>Submit Another Request</a>
        </p>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <div class="card">
                <div class="card-body">
                    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                        <DataAnnotationsValidator />
                        <ValidationSummary class="text-danger mb-3" />

                        <div class="mb-3">
                            <label for="studentName" class="form-label">Full Name</label>
                            <InputText id="studentName" class="form-control" @bind-Value="_model.StudentName" />
                            <ValidationMessage For="() => _model.StudentName" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label">Student ID</label>
                            <InputText id="studentId" class="form-control" @bind-Value="_model.StudentId" placeholder="e.g., CS123456" />
                            <ValidationMessage For="() => _model.StudentId" class="text-danger" />
                            <div class="form-text">Format: 2 uppercase letters followed by 6 digits</div>
                        </div>

                        <div class="mb-3">
                            <label for="courseId" class="form-label">Course</label>
                            <InputSelect id="courseId" class="form-select" @bind-Value="_model.CourseId">
                                <option value="0">— Select a course —</option>
                                @if (_courses is not null)
                                {
                                    @foreach (var course in _courses)
                                    {
                                        <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr.)</option>
                                    }
                                }
                            </InputSelect>
                            <ValidationMessage For="() => _model.CourseId" class="text-danger" />
                        </div>

                        <div class="mb-3">
                            <label for="comments" class="form-label">Comments (optional)</label>
                            <InputTextArea id="comments" class="form-control" rows="3" @bind-Value="_model.Comments" />
                            <ValidationMessage For="() => _model.Comments" class="text-danger" />
                        </div>

                        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                    </EditForm>
                </div>
            </div>
        </div>

        <div class="col-lg-4">
            <div class="card bg-light">
                <div class="card-body">
                    <h5 class="card-title">How It Works</h5>
                    <ol class="mb-0">
                        <li>Fill out the enrollment request form.</li>
                        <li>Your request will be reviewed by the registrar.</li>
                        <li>You'll receive a confirmation email within 2 business days.</li>
                    </ol>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private EnrollmentRequest _model = new();
    private List<Course>? _courses;
    private bool _submitted;

    [SupplyParameterFromQuery(Name = "course")]
    public int? PreselectedCourseId { get; set; }

    protected override async Task OnInitializedAsync()
    {
        _courses = await CatalogService.GetCoursesAsync();

        if (PreselectedCourseId.HasValue)
        {
            _model.CourseId = PreselectedCourseId.Value;
        }
    }

    private async Task HandleSubmit()
    {
        var success = await CatalogService.SubmitEnrollmentRequestAsync(_model);
        if (success)
        {
            _submitted = true;
        }
    }

    private void ResetForm()
    {
        _model = new EnrollmentRequest();
        _submitted = false;
    }
}

